function sliderMain() {
    var swiper = new Swiper('.main .mySwiper', {
        slidesPerView: 1,
        spaceBetween: 15,
        speed: 500,
        navigation: {
            nextEl: ".main .swiper-button-next",
            prevEl: ".main .swiper-button-prev",
        },
        pagination: {
            el: ".main .swiper-pagination",
            clickable: true
        },
    })
}

function sliderFeedback() {
    var swiper = new Swiper('.feedback .mySwiper', {
        slidesPerView: 1.4,
        spaceBetween: 32,
        speed: 500,
        navigation: {
            nextEl: ".feedback .swiper-button-next",
            prevEl: ".feedback .swiper-button-prev",
        },
        pagination: {
            el: ".feedback .swiper-pagination",
            clickable: true
        },
        breakpoints: {
            320: {
                slidesPerView: 1,
                spaceBetween: 15,
            },
            577: {
                slidesPerView: 1.31,
                spaceBetween: 32,
            },
        }
    })
}

function sliderProductMain() {
    var swiper = new Swiper(".product-main__slider .mySwiper", {
        slidesPerView: 5,
        spaceBetween: 12,
        freeMode: true,
        watchSlidesProgress: true,
        direction: "vertical",
        breakpoints: {
            320: {
                spaceBetween: 7,
                direction: "horizontal",
            },
            577: {
                spaceBetween: 12,
                direction: "vertical",
            }
        }
    });
    var swiper2 = new Swiper(".product-main__slider .mySwiper2", {
        spaceBetween: 12,
        slidesPerView: 1,
        thumbs: {
            swiper: swiper,
        },
        navigation: {
            nextEl: ".swiper-button-next",
            prevEl: ".swiper-button-prev",
        },
    });
}

function sliderFeedback2() {
    var swiper = new Swiper('.feedback2 .mySwiper', {
        slidesPerView: 2,
        spaceBetween: 20,
        speed: 500,
        navigation: {
            nextEl: ".feedback2 .swiper-button-next",
            prevEl: ".feedback2 .swiper-button-prev",
        },
        pagination: {
            el: ".feedback2 .swiper-pagination",
            clickable: true
        },
        breakpoints: {
            320: {
                slidesPerView: 1,
            },
            744: {
                slidesPerView: 2,
            },
        }
    })
}

$(document).ready(function () {
    sliderMain();
    sliderFeedback();
    sliderProductMain();
    sliderFeedback2();

    // Menu
    $('.burger').click(function () {
        $('.header-menu').addClass('header-menu--active')
        $('body').addClass('fixed-body')
    })

    $('.header-menu__close').click(function () {
        $('.header-menu').removeClass('header-menu--active')
        $('body').removeClass('fixed-body')
    })

    $('.header-menu__bg').click(function () {
        $(this).parents('.header-menu').removeClass('header-menu--active')
        $('body').removeClass('fixed-body')
    })

    // Search
    $('.header__search-btn').click(function () {
        $(this).parents('.header__inner').addClass('search-active')
    })

    $('.header__search-close').click(function () {
        const $header = $(this).closest('.header__inner');

        $header.removeClass('search-active');
        $header.find('.search__input').val('').trigger('input');
    });

    $('.search__input').on('input', function () {
        $(this)
            .siblings('.search__clear')
            .toggleClass('active', $(this).val().length > 0);
    });

    $('.search__clear').on('click', function () {
        $(this)
            .removeClass('active')
            .siblings('.search__input')
            .val('')
            .focus();
    });

    // Favorite
    $('.favorite').click(function () {
        $(this).toggleClass('favorite--active')
    })

    // Select
    $('.custom-select').niceSelect();

    // Filter
    $('.filter__btn').click(function () {
        $('.filter-menu').addClass('filter-menu--active')
        $('body').addClass('fixed-body')
    })

    $('.filter__close, .filter__close2').click(function () {
        $('.filter-menu').removeClass('filter-menu--active')
        $('body').removeClass('fixed-body')
    })

    // Fancybox
    Fancybox.bind("[data-fancybox]", {});

    // Calc
    function calc(){
        $('.calc .calc-minus').click(function(){
            let a = $(this).closest('.calc').find('input').val();
            if(a>1){
                let b = +a-1;
                $(this).closest('.calc').find('input').val(b);
            }else{
                $(this).closest('.calc').find('input').val(a);
            }
        });
        $('.calc .calc-plus').click(function(){
            let a = $(this).closest('.calc').find('input').val();
            let b = +a+1;
            $(this).closest('.calc').find('input').val(b);
        });
    }
    calc()

    // Tabs
    $(".tab").click(function () {
        let path = $(this).attr("data-tab-path")
        $(this).siblings(".tab").removeClass("tab--active")
        $(this).addClass("tab--active")

        $(this).parents(".tabs-inner").find(".tab__content").removeClass("tab__content--active")
        $(this).parents(".tabs-inner").find(`.tab__content[data-content-path="${path}"]`).addClass("tab__content--active")
    })

})